@namespace sv_0ee419f6c2034e41b2fc401e1a82cb82.Components.Pages.Board

<div class="task-card">
    <h4 class="task-title">@Task.Title</h4>
    <p class="task-assignee">@Task.Assignee</p>
    <span class="priority-badge priority-@Task.Priority.ToLowerInvariant()">@Task.Priority</span>
    <span class="task-due-date">@Task.DueDate.ToString("MMM dd")</span>
    <div class="task-actions">
        @if (CanMoveLeft)
        {
            <button class="btn-move btn-move-left" @onclick="OnMoveLeftClick">Move Left</button>
        }
        @if (CanMoveRight)
        {
            <button class="btn-move btn-move-right" @onclick="OnMoveRightClick">Move Right</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback OnMoveLeft { get; set; }
    [Parameter] public EventCallback OnMoveRight { get; set; }

    private async System.Threading.Tasks.Task OnMoveLeftClick() => await OnMoveLeft.InvokeAsync();
    private async System.Threading.Tasks.Task OnMoveRightClick() => await OnMoveRight.InvokeAsync();
}

@namespace sv_0ee419f6c2034e41b2fc401e1a82cb82.Components.Pages.Board

<div class="add-task-form">
    <input type="text" placeholder="Title" @bind="title" class="form-input" />
    <input type="text" placeholder="Assignee" @bind="assignee" class="form-input" />
    <select @bind="priority" class="form-input">
        <option value="High">High</option>
        <option value="Medium">Medium</option>
        <option value="Low">Low</option>
    </select>
    <input type="date" @bind="dueDate" class="form-input" />
    <div class="form-actions">
        <button class="btn-save" @onclick="HandleSave">Save</button>
        <button class="btn-cancel" @onclick="HandleCancel">Cancel</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string DefaultStatus { get; set; } = default!;
    [Parameter] public EventCallback<NewTaskModel> OnSave { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private string title = string.Empty;
    private string assignee = string.Empty;
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);

    private async Task HandleSave()
    {
        if (string.IsNullOrWhiteSpace(title)) return;
        await OnSave.InvokeAsync(new NewTaskModel(title, assignee, priority, dueDate));
        title = string.Empty;
        assignee = string.Empty;
        priority = "Medium";
        dueDate = DateTime.Today.AddDays(7);
    }

    private async Task HandleCancel() => await OnCancel.InvokeAsync();

    public record NewTaskModel(string Title, string Assignee, string Priority, DateTime DueDate);
}

@namespace sv_0ee419f6c2034e41b2fc401e1a82cb82.Components.Pages.Board

<div class="kanban-column">
    <div class="column-header">
        <h3>@Title (@Tasks.Count)</h3>
    </div>
    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      CanMoveLeft="CanMoveLeft"
                      CanMoveRight="CanMoveRight"
                      OnMoveLeft="() => HandleMoveLeft(task)"
                      OnMoveRight="() => HandleMoveRight(task)" />
        }
    </div>
    <div class="column-footer">
        @if (showForm)
        {
            <AddTaskForm DefaultStatus="@Status"
                         OnSave="HandleAddTask"
                         OnCancel="() => showForm = false" />
        }
        else
        {
            <button class="btn-add-task" @onclick="() => showForm = true">Add Task</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string Title { get; set; } = default!;
    [Parameter, EditorRequired] public string Status { get; set; } = default!;
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveRight { get; set; }
    [Parameter] public EventCallback<AddTaskForm.NewTaskModel> OnAddTask { get; set; }

    private bool showForm;

    private async Task HandleMoveLeft(TaskItem task) => await OnMoveLeft.InvokeAsync(task);
    private async Task HandleMoveRight(TaskItem task) => await OnMoveRight.InvokeAsync(task);

    private async Task HandleAddTask(AddTaskForm.NewTaskModel model)
    {
        await OnAddTask.InvokeAsync(model);
        showForm = false;
    }
}

@namespace sv_0ee419f6c2034e41b2fc401e1a82cb82.Components.Pages.Board

<div class="board-search">
    <input type="text"
           placeholder="Search tasks by title..."
           value="@SearchText"
           @oninput="HandleInput"
           class="search-input" />
</div>

@code {
    [Parameter] public string SearchText { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> SearchTextChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? string.Empty;
        await SearchTextChanged.InvokeAsync(value);
    }
}

@page "/board"
@namespace sv_0ee419f6c2034e41b2fc401e1a82cb82.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<div class="kanban-board">
    @if (isLoading)
    {
        <p class="board-loading">Loading tasks...</p>
    }
    else if (errorMessage is not null)
    {
        <p class="board-error">@errorMessage</p>
    }
    else
    {
        <BoardStats Tasks="allTasks" />
        <BoardSearchBar SearchText="@searchText" SearchTextChanged="HandleSearchChanged" />

        <div class="kanban-columns">
            <KanbanColumn Title="To Do"
                          Status="To Do"
                          Tasks="GetFilteredTasks("To Do")"
                          CanMoveLeft="false"
                          CanMoveRight="true"
                          OnMoveRight="task => MoveTask(task, "In Progress")"
                          OnAddTask="model => AddTask(model, "To Do")" />

            <KanbanColumn Title="In Progress"
                          Status="In Progress"
                          Tasks="GetFilteredTasks("In Progress")"
                          CanMoveLeft="true"
                          CanMoveRight="true"
                          OnMoveLeft="task => MoveTask(task, "To Do")"
                          OnMoveRight="task => MoveTask(task, "Done")"
                          OnAddTask="model => AddTask(model, "In Progress")" />

            <KanbanColumn Title="Done"
                          Status="Done"
                          Tasks="GetFilteredTasks("Done")"
                          CanMoveLeft="true"
                          CanMoveRight="false"
                          OnMoveLeft="task => MoveTask(task, "In Progress")"
                          OnAddTask="model => AddTask(model, "Done")" />
        </div>
    }
</div>

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var tasks = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return tasks.ToList();
    }

    private void HandleSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                allTasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task AddTask(AddTaskForm.NewTaskModel model, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
            allTasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to add task: {ex.Message}";
        }
    }
}

